import "mylib";
// The augmentation of another package's CLASS, seen from a VALUE position.
// `new Widget()` builds its instance from the class symbol, not from the
// merged symbol a type annotation resolves to, so the two views of one class
// used to be different shapes — and `function f(): Widget { return new
// Widget(...) }` was a phantom TS2739.
declare module "mylib" {
  interface Widget {
    extra: number;
  }
}
